function inversions(a) {
  if (a.length <= 1) return { sorted: a, count: 0 };
  const mid = Math.floor(a.length / 2);
  const L = inversions(a.slice(0, mid));
  const R = inversions(a.slice(mid));
  let count = L.count + R.count;
  const out = [];
  let i = 0;
  let j = 0;
  while (i < L.sorted.length && j < R.sorted.length) {
    if (R.sorted[j] < L.sorted[i]) {
      count += L.sorted.length - i;
      out.push(R.sorted[j++]);
    } else out.push(L.sorted[i++]);
  }
  return { sorted: out.concat(L.sorted.slice(i), R.sorted.slice(j)), count };
}

