function pow(x, n, stats) {
  if (n === 0) return 1;
  const half = pow(x, Math.floor(n / 2), stats);
  let result = half * half;
  stats.m++;
  if (n % 2 === 1) {
    result = result * x;
    stats.m++;
  }
  return result;
}

