function kthSmallest(values, k) {
  let items = values;
  while (true) {
    const pivot = items[Math.floor(items.length / 2)];
    const smaller = items.filter((v) => v < pivot);
    const equal = items.filter((v) => v === pivot);
    if (k < smaller.length) {
      items = smaller;
    } else if (k < smaller.length + equal.length) {
      return pivot;
    } else {
      k -= smaller.length + equal.length;
      items = items.filter((v) => v > pivot);
    }
  }
}

const minutes = [40, 15, 90, 35, 20, 35, 60];
console.log(kthSmallest(minutes, 3), kthSmallest(minutes, 0), kthSmallest(minutes, 6), kthSmallest([20, 20, 20], 1));

