function countFlips(ranks) {
  function sortCount(a) {
    if (a.length <= 1) return [a, 0];
    const mid = Math.floor(a.length / 2);
    const [left, leftCount] = sortCount(a.slice(0, mid));
    const [right, rightCount] = sortCount(a.slice(mid));
    let count = leftCount + rightCount;
    const out = [];
    let i = 0;
    let j = 0;
    while (i < left.length && j < right.length) {
      if (right[j] < left[i]) {
        count += left.length - i;
        out.push(right[j++]);
      } else {
        out.push(left[i++]);
      }
    }
    return [out.concat(left.slice(i), right.slice(j)), count];
  }
  return sortCount(ranks)[1];
}

