function multiply(a, b) {
  return [
    [a[0][0] * b[0][0] + a[0][1] * b[1][0], a[0][0] * b[0][1] + a[0][1] * b[1][1]],
    [a[1][0] * b[0][0] + a[1][1] * b[1][0], a[1][0] * b[0][1] + a[1][1] * b[1][1]],
  ];
}

function matrixPower(m, n) {
  if (n === 0) return [[1, 0], [0, 1]];
  const half = matrixPower(m, Math.floor(n / 2));
  const squared = multiply(half, half);
  return n % 2 === 1 ? multiply(squared, m) : squared;
}

function fib(n) {
  return matrixPower([[1, 1], [1, 0]], n)[0][1];
}

console.log(fib(0), fib(1), fib(10), fib(50));
